  "company_fn",
  "id",
  CASE
    WHEN "type" = 'income' THEN 'revenue'
    WHEN "type" = 'expense' AND "code" LIKE '5%' THEN 'cost_of_sales'
    WHEN "type" = 'expense' THEN 'operating_expense'
  END,
  ROW_NUMBER() OVER (
    PARTITION BY "master_fn", "company_fn", "type"
    ORDER BY "code", "id"
