--> statement-breakpoint
CREATE TRIGGER expense_claim_line_draft_only
BEFORE INSERT OR UPDATE OR DELETE ON expense_claim_line
FOR EACH ROW EXECUTE FUNCTION enforce_expense_claim_draft_child_mutation();
